with deduped as (select * from payments qualify rank() over (partition by status order by amount desc nulls last) = 1) select date_trunc('month', paid_at) as activity_month, max(amount) filter (where status = 'REFUNDED') as refunded_max_amount, min(amount) as min_amount, round(sum(amount) / nullif(count(case when method = 'card' then 1 end), 0), 2) as amount_per_card from deduped group by 1 order by activity_month nulls first;
